// src/services/api.js — ЗАМОКОВЫЙ ВАРИАНТ (БЕЗ БЭКЕНДА)

console.log("API замокан — бэкенд не нужен!");

const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

const mockUser = {
  id: 1,
  username: "testuser",
  email: "test@example.com",
};

// === АВТОРИЗАЦИЯ ===
export const authAPI = {
  login: async (email, password) => {
    await delay(800);
    if (email === "test@example.com" && password === "testpassword123") {
      return { data: { user: mockUser } };
    }
    throw new Error("Неверный логин или пароль");
  },

  register: async (userData) => {
    await delay(800);
    return { data: { ...userData, id: 1 } };
  },

  logout: async () => {
    await delay(300);
    return { data: { message: "Logged out" } };
  },

  getMe: async () => {
    await delay(500);
    return { data: mockUser };
  },
};

// === ТОРГОВЛЯ ===
export const tradeAPI = {
  executeOrder: async (orderData) => {
    await delay(600);
    return { data: { status: "executed", ...orderData } };
  },

  getPortfolio: async () => {
    await delay(700);
    return {
      data: {
        total_value: 125000.50,
        cash_balance: 45230.75,
        positions_count: 3,
        positions: [
          { figi: "BBG000B9XRY4", quantity: 10, value: 1950.00, change: 2.4 },
          { figi: "BBG000BVPV84", quantity: 5,  value: 2850.00, change: -0.8 },
          { figi: "BBG006L8G4H4", quantity: 8,  value: 1240.00, change: 5.1 },
        ]
      }
    };
  },
};

// === РЫНОК ===
export const marketAPI = {
  loadCandles: async (figi, days) => {
    await delay(900);
    return {
      data: {
        candles_saved: 168,
        status: "success",
      }
    };
  },
};
